import{_ as a,b as t,a as e,aS as o}from"./chunks/framework.M2Whok06.js";const u=JSON.parse('{"title":"战争片","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/战争片.md","filePath":"note/movie/战争片.md","lastUpdated":1745418772000}'),i={name:"note/movie/战争片.md"},r=o('<h1 id="战争片" tabindex="-1">战争片 <a class="header-anchor" href="#战争片" aria-label="Permalink to &quot;战争片&quot;">​</a></h1><p>战争片对我来说是非常严肃的，我不会推荐那些抗日神剧。所以单开一篇来分享。希望大家铭记历史。</p><h2 id="血战台儿庄" tabindex="-1">血战台儿庄 <a class="header-anchor" href="#血战台儿庄" aria-label="Permalink to &quot;血战台儿庄&quot;">​</a></h2><p><strong>历史意义：</strong></p><p>‌血战台儿庄的历史意义在于它是中国抗日战争中的一次重要胜利，极大地鼓舞了全国军民的士气，改变了国际视听。‌这次战役发生在1938年3月16日至4月15日，以山东枣庄台儿庄为中心的鲁南区域展开，国民革命军与日军进行了激烈的战斗。中国军队约有29万人参战，日军约有5万人参战。战役中，中国军队伤亡约5万余人，毙伤日军约1万余人。这次胜利不仅打击了日本侵略者的嚣张气焰，还坚定了全国军民坚持抗战的信心。‌</p><p>此外，血战台儿庄也是抗日战争以来取得的最大胜利之一，是徐州会战中国民革命军取得的一次重大胜利。战役由李宗仁、白崇禧、孙连仲、汤恩伯等抗日将领指挥。蒋介石也曾三次赴徐州视察、督导、调配兵力，并在台儿庄战斗最激烈的时刻亲赴台儿庄南站观战，勉励前线将士。</p><p><strong>电影政治意义：</strong> ‌《血战台儿庄》电影在文化和社会影响方面具有深远的意义。‌该电影不仅在电影艺术上取得了成功，还对两岸关系产生了重要影响。影片上映后，受到了两岸三地及海内外的广泛好评，时任中央统战部部长的阎明复甚至认为这部电影的效果胜过多年的统战工作。此外，影片在台湾的上映引起了强烈的反响，蒋经国和宋美龄都观看了这部电影，并决定开放国民党老兵回大陆探亲，这标志着海峡两岸关系的重大突破。‌</p><ul><li>1986-01-01 中国大陆 129分钟</li><li>类型：战争 历史</li><li>导演：杨光远 翟俊杰</li><li>主演：邵宏来 江化霖 翟俊杰 赵恒多 宋广汉</li><li>百科：1938年,日寇占领民国首府南京之后,计划由南北两面包抄津浦路遇陇海路的枢纽华东重镇徐州,以实现对华东的全面占领... <img src="https://img2.baidu.com/it/u=847239811,2852972974&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=988&amp;h=800" alt=""></li></ul>',8),s=[r];function l(n,p,_,c,m,d){return e(),t("div",null,s)}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
